  Name extends Extract<DeepKeys<z.input<Schema>>, string>,
> = FieldApi<
  z.input<Schema>,
  Name,
  DeepValue<z.input<Schema>, Name>,
  undefined,
  undefined,
  undefined,
  undefined,
  undefined,
  undefined,
  undefined,
